//! Evidence suite #1: cross-implementation verification against the independent
//! Python reference oracle.
//!
//! The Rust core is never used as its own oracle here:
//! * frames from `tests/fixtures` are generated by `reference/ref_lz77.py`;
//! * every good fixture is decoded by BOTH implementations and the bytes, digests
//!   and intermediate token statistics are compared;
//! * every malformed fixture is rejected by BOTH with the SAME error category;
//! * frames freshly produced by the Rust encoder are decoded by Python, and frames
//!   produced by Python's brute-force encoder are decoded by Rust.

mod common;

use common::*;
use lz77_blocks::codec;
use lz77_blocks::error::ErrorCategory;
use lz77_blocks::format::{self, dictionary_digest, BlockMode, WINDOW_BYTES};
use serde_json::{json, Value};

#[test]
fn good_fixtures_decode_identically_in_both_implementations() {
    let mut log = TestLog::new("oracle_crosscheck");
    if !oracle_available() {
        log.skip("all", "python3 not available", json!({}));
        println!("{}", log.finish());
        return;
    }
    let cases = fixture_cases();
    let mut failures: Vec<String> = Vec::new();

    for (name, case) in cases.iter().filter(|(_, c)| c["kind"] == "good") {
        let frame = fixture(case["file"].as_str().unwrap());
        let frame_path = fixtures_dir().join(case["file"].as_str().unwrap());

        // Dictionary handling mirrors the fixture declaration.
        let dictionary = if case.get("mode").and_then(Value::as_str) == Some("dependent") {
            // The digest alone is not the dictionary; for good chain fixtures we
            // assemble it from the previous slices of source.bin.
            assemble_chain_dictionary(&cases, name)
        } else {
            Vec::new()
        };

        // Rust side
        let rust = codec::decode_one(&frame, &dictionary);
        // Python side
        let (oracle, oracle_bytes) = oracle_decode_paths(&frame_path, &dictionary);

        let state = json!({
            "fixture": case["file"],
            "mode": case.get("mode"),
            "declared_data_len": case.get("slice"),
            "oracle_valid": oracle.valid(),
            "oracle_category": oracle.category(),
            "oracle_stats": oracle.json.get("stats"),
            "oracle_sha256": oracle.json.get("sha256"),
        });

        match (&rust, oracle.valid()) {
            (Ok(rust_out), true) => {
                let oracle_out = oracle_bytes.expect("valid decode yields bytes");
                let same = rust_out.as_slice() == oracle_out.as_slice();
                // Fixture manifest pins the expected SHA-256.
                let want_sha = case.get("output_sha256").and_then(Value::as_str);
                let sha_ok = want_sha.map(|w| w == format_sha(rust_out)).unwrap_or(true);
                if same && sha_ok {
                    let mut s = state.as_object().unwrap().clone();
                    s.insert("rust_len".into(), json!(rust_out.len()));
                    s.insert("rust_sha256".into(), json!(format_sha(rust_out)));
                    log.pass(
                        name,
                        "both implementations decoded identical bytes; digest matches manifest",
                        Value::Object(s),
                    );
                } else {
                    let reason = format!(
                        "mismatch: bytes_equal={same}, sha_ok={sha_ok}, want_sha={want_sha:?}"
                    );
                    log.fail(name, &reason, state.clone());
                    failures.push(name.clone());
                }
            }
            (Err(e), false) => {
                let mut s = state.as_object().unwrap().clone();
                s.insert("rust_error".into(), json!(e.to_string()));
                log.fail(
                    name,
                    "both implementations rejected a fixture declared good",
                    Value::Object(s),
                );
                failures.push(name.clone());
            }
            (Ok(_), false) => {
                log.fail(name, "Rust accepted but reference rejected", state);
                failures.push(name.clone());
            }
            (Err(e), true) => {
                let mut s = state.as_object().unwrap().clone();
                s.insert("rust_error".into(), json!(e.to_string()));
                log.fail(
                    name,
                    "reference accepted but Rust rejected",
                    Value::Object(s),
                );
                failures.push(name.clone());
            }
        }
    }

    let path = log.finish();
    assert!(
        failures.is_empty(),
        "good-fixture failures: {failures:?}; log {path}"
    );
}

#[test]
fn malformed_fixtures_are_rejected_with_expected_categories_by_both() {
    let mut log = TestLog::new("oracle_crosscheck");
    if !oracle_available() {
        log.skip("all", "python3 not available", json!({}));
        println!("{}", log.finish());
        return;
    }
    let cases = fixture_cases();
    let mut failures: Vec<String> = Vec::new();

    for (name, case) in cases.iter().filter(|(_, c)| c["kind"] == "bad") {
        let frame = fixture(case["file"].as_str().unwrap());
        let frame_path = fixtures_dir().join(case["file"].as_str().unwrap());
        let want_category = case["expect"]["category"].as_str().unwrap();

        // Assemble the dictionary the scenario requires (state-conflict cases).
        let dictionary = assemble_bad_dictionary(case);

        let rust = codec::decode_one(&frame, &dictionary);
        let (oracle, _oracle_bytes) = oracle_decode_paths(&frame_path, &dictionary);

        let rust_category = rust.as_ref().err().map(|e| e.category.as_ref().to_string());
        let oracle_category = oracle.category();
        let state = json!({
            "fixture": case["file"],
            "expected_category": want_category,
            "rust_category": rust_category,
            "oracle_category": oracle_category,
            "rust_detail": rust.as_ref().err().map(|e| e.detail.clone()),
            "oracle_reason": oracle.json.get("reason"),
            "intermediate": case.get("intermediate"),
            "manifest_rationale": case.get("rationale"),
        });

        let rust_ok = rust_category.as_deref() == Some(want_category);
        let oracle_ok = oracle_category.as_deref() == Some(want_category);
        if rust_ok && oracle_ok {
            log.pass(
                name,
                "Rust and independent reference agree on the failure category",
                state,
            );
        } else {
            log.fail(
                name,
                "category disagreement between implementations or with manifest",
                state,
            );
            failures.push(name.clone());
        }
    }

    let path = log.finish();
    assert!(
        failures.is_empty(),
        "malformed-fixture failures: {failures:?}; log {path}"
    );
}

#[test]
fn self_overlap_long_match_expands_byte_by_byte() {
    let mut log = TestLog::new("oracle_crosscheck");
    let frame = fixture("good/self_overlap_rle.frame");
    let out = codec::decode_one(&frame, b"").expect("fixture decodes");

    let expected = b"a".repeat(259);
    let exact = out == expected;
    // A single match of length 258 at distance 1 is what the frame encodes.
    let envelope = format::decode_frame(&frame).unwrap();
    let contains_dist1_match = envelope.payload.windows(4).any(|w| {
        w[0] == format::CTRL_MATCH && u16::from_le_bytes([w[1], w[2]]) == 1 && w[3] == 255
    });

    let state = json!({
        "len": out.len(),
        "first_8": &out[..8.min(out.len())],
        "distance": 1,
        "match_length": 258,
        "naive_slice_copy_would_yield": "aaaaaaaa with duplicated prefix garbage / panic",
    });
    if exact && contains_dist1_match {
        log.pass(
            "self_overlap_rle",
            "length 258 > distance 1 produced exactly 259 'a' bytes (run semantics)",
            state,
        );
    } else {
        log.fail("self_overlap_rle", "overlap expansion wrong", state);
    }

    // Same assertion through the independent decoder.
    if oracle_available() {
        let frame_path = fixtures_dir().join("good/self_overlap_rle.frame");
        let (rep, _bytes) = oracle_decode_paths(&frame_path, b"");
        assert!(rep.valid());
        assert_eq!(rep.json["stats"]["overlap_copies"], 1);
    }
    println!("{}", log.finish());
    assert!(exact && contains_dist1_match);
}

#[test]
fn cross_window_boundary_distance_4096_accepted_and_4097_rejected() {
    let mut log = TestLog::new("oracle_crosscheck");
    let mut failures: Vec<String> = Vec::new();

    // Fixture: 'XYZ' at offset 0 matched from offset 4096 at distance exactly WINDOW.
    let frame = fixture("good/cross_window_boundary.frame");
    let out = codec::decode_one(&frame, b"").expect("boundary fixture decodes");
    let envelope = format::decode_frame(&frame).unwrap();
    let boundary_seen = oracle_fixture_has_boundary_match(envelope.payload);

    if out.starts_with(b"XYZ") && out[WINDOW_BYTES..WINDOW_BYTES + 3] == b"XYZ"[..] && boundary_seen
    {
        log.pass(
            "cross_window_boundary",
            "match at distance exactly 4096 accepted; bytes at both offsets equal XYZ",
            json!({"distance": WINDOW_BYTES, "window_bytes": WINDOW_BYTES}),
        );
    } else {
        log.fail(
            "cross_window_boundary",
            "boundary handling incorrect",
            json!({"boundary_match_token_present": boundary_seen}),
        );
        failures.push("cross_window_boundary".to_string());
    }

    // Distance 4097 (0x1001) against a full 4096-byte dictionary: bind is valid,
    // the token is not. Must be input_error, never state/resource.
    let dict = vec![0x41u8; WINDOW_BYTES];
    let digest = dictionary_digest(&dict);
    let malicious_payload = [format::CTRL_MATCH, 0x01, 0x10, 0x00, format::CTRL_END];
    let bad = format::encode_frame(BlockMode::Dependent, &digest, 3, &malicious_payload);
    let err = codec::decode_one(&bad, &dict).unwrap_err();
    if err.category == ErrorCategory::Input && err.detail.contains("exceeds fixed window") {
        log.pass(
            "distance_4097_with_full_dictionary",
            "even with valid binding/history, distance 4097 is rejected as input_error",
            json!({"distance": 4097, "category": err.category.as_ref(), "detail": err.detail}),
        );
    } else {
        log.fail(
            "distance_4097_with_full_dictionary",
            "wrong category for beyond-window distance",
            json!({"error": err.to_string()}),
        );
        failures.push("distance_4097".to_string());
    }

    let path = log.finish();
    assert!(failures.is_empty(), "{failures:?}; log {path}");
}

#[test]
fn different_chunk_modes_recover_identical_bytes() {
    let mut log = TestLog::new("oracle_crosscheck");
    let mut failures: Vec<String> = Vec::new();
    let source = source_bytes();
    let cases = fixture_cases();

    // Mode A: one independent block.
    let one = {
        let f = fixture(cases["one_independent"]["file"].as_str().unwrap());
        codec::decode_one(&f, b"").unwrap()
    };
    // Mode B: three independent blocks concatenated.
    let three: Vec<u8> = (0u8..3)
        .flat_map(|i| {
            let rel = cases[&format!("three_independent_{i}")]["file"]
                .as_str()
                .unwrap();
            codec::decode_one(&fixture(rel), b"").unwrap()
        })
        .collect();
    // Mode C: independent root + dependent chain.
    let chain_frames: Vec<Vec<u8>> = (0u8..3)
        .map(|i| fixture(cases[&format!("chain_{i}")]["file"].as_str().unwrap()))
        .collect();
    let chain = codec::decode_chain(&chain_frames).unwrap();
    // Mode D: alternative split, root + four dependents.
    let alt_frames: Vec<Vec<u8>> = (0u8..5)
        .map(|i| fixture(cases[&format!("chain_alt_{i}")]["file"].as_str().unwrap()))
        .collect();
    let alt = codec::decode_chain(&alt_frames).unwrap();

    for (label, bytes) in [
        ("one_independent", &one),
        ("three_independent", &three),
        ("dependent_chain_3", &chain),
        ("dependent_chain_5", &alt),
    ] {
        let eq = bytes.as_slice() == source.as_slice();
        let state = json!({"len": bytes.len(), "source_len": source.len(),
            "sha256": format_sha(bytes), "source_sha256": format_sha(&source)});
        if eq {
            log.pass(label, "recovered bytes identical to source.bin", state);
        } else {
            log.fail(label, "chunking mode changed recovered bytes", state);
            failures.push(label.to_string());
        }
    }

    // Cross-check mode C/D with the Python reference, feeding the chain dictionary
    // incrementally exactly like a streaming receiver.
    if oracle_available() {
        for (prefix, count, label) in [
            ("chain", 3usize, "oracle_chain_3"),
            ("chain_alt", 5usize, "oracle_chain_5"),
        ] {
            let mut combined: Vec<u8> = Vec::new();
            let mut ok = true;
            for i in 0..count {
                let rel = cases[&format!("{prefix}_{i}")]["file"].as_str().unwrap();
                let path = fixtures_dir().join(rel);
                let (rep, bytes) = oracle_decode_paths(&path, &combined);
                if !rep.valid() {
                    ok = false;
                    log.fail(
                        label,
                        &format!("reference rejected {prefix}_{i}: {}", rep.json),
                        json!({}),
                    );
                    break;
                }
                combined.extend_from_slice(&bytes.expect("valid decode yields bytes"));
            }
            if ok && combined == source {
                log.pass(
                    label,
                    "independent reference streams the chain to identical bytes",
                    json!({"len": combined.len()}),
                );
            } else if ok {
                failures.push(label.to_string());
                log.fail(
                    label,
                    "reference chain output differs from source",
                    json!({}),
                );
            } else {
                failures.push(label.to_string());
            }
        }
    }

    let path = log.finish();
    assert!(
        failures.is_empty(),
        "chunking failures: {failures:?}; log {path}"
    );
}

#[test]
fn frames_cross_produced_by_each_implementation_are_accepted() {
    let mut log = TestLog::new("oracle_crosscheck");
    if !oracle_available() {
        log.skip("cross_production", "python3 not available", json!({}));
        println!("{}", log.finish());
        return;
    }
    let mut failures: Vec<String> = Vec::new();
    let payloads: Vec<(&str, Vec<u8>)> = vec![
        ("short", b"hello world".to_vec()),
        ("repetitive", b"abc".repeat(500)),
        ("mixed", {
            let mut v = b"prefix ".to_vec();
            v.extend((0u32..5000).map(|i| (i.wrapping_mul(2654435761) >> 24) as u8));
            v.extend(b"abcabcabc".repeat(50));
            v
        }),
        ("empty", vec![]),
    ];

    for (name, data) in &payloads {
        // Rust encoder -> Python decoder.
        let rust_frame = codec::encode_independent(data);
        let (rep, out) = oracle_roundtrip(&rust_frame, b"");
        let rust_to_py = rep.valid() && out.as_deref() == Some(data.as_slice());

        // Python encoder -> Rust decoder.
        let py_frame = oracle_encode(data, "independent", b"");
        let rust_decoded = codec::decode_one(&py_frame, b"");
        let py_to_rust = match rust_decoded {
            Ok(b) => &b == data,
            Err(_) => false,
        };

        // Frames must differ structurally (different parsers) yet be semantically equal.
        let structurally_different = rust_frame != py_frame || data.len() < 3;

        let state = json!({
            "data_len": data.len(),
            "rust_frame_len": rust_frame.len(),
            "python_frame_len": py_frame.len(),
            "rust_to_python_ok": rust_to_py,
            "python_to_rust_ok": py_to_rust,
            "independently_encoded_frames_differ": structurally_different,
        });
        if rust_to_py && py_to_rust {
            log.pass(
                &format!("cross_{name}"),
                "both implementations decode each other's frames to identical bytes",
                state,
            );
        } else {
            log.fail(&format!("cross_{name}"), "cross-decoding failed", state);
            failures.push(name.to_string());
        }
    }

    // Dependent cross-production with a 4096+ byte history (exercises window tail).
    let history = {
        let mut h = Vec::new();
        for i in 0..9000u32 {
            h.push((i % 251) as u8);
        }
        h
    };
    let block: Vec<u8> = (0..2000u32).map(|i| ((i + 1000) % 251) as u8).collect();

    let rust_dep = codec::encode_dependent(&block, &history).unwrap();
    let (rep, out) = oracle_roundtrip(&rust_dep, &history);
    if rep.valid() && out.as_deref() == Some(block.as_slice()) {
        log.pass(
            "cross_dependent_over_window",
            "Rust dependent frame (>1-window history) decoded by reference",
            json!({"history_len": history.len(), "oracle_category": rep.category()}),
        );
    } else {
        log.fail(
            "cross_dependent_over_window",
            "reference failed to decode Rust dependent frame",
            json!({"report": rep.json}),
        );
        failures.push("cross_dependent".to_string());
    }

    let py_dep = oracle_encode(&block, "dependent", &history);
    match codec::decode_one(&py_dep, &history) {
        Ok(b) if b == block => log.pass(
            "cross_dependent_py_to_rust",
            "reference dependent frame decoded by Rust against long history",
            json!({"frame_len": py_dep.len()}),
        ),
        other => {
            log.fail(
                "cross_dependent_py_to_rust",
                "Rust rejected reference dependent frame",
                json!({"result": other.map(|_| ()).err().map(|e| e.to_string())}),
            );
            failures.push("cross_dependent_py_to_rust".to_string());
        }
    }

    let path = log.finish();
    assert!(
        failures.is_empty(),
        "cross-production failures: {failures:?}; log {path}"
    );
}

// ------------------------------------------------------------------------ helpers

fn format_sha(bytes: &[u8]) -> String {
    use sha2::{Digest, Sha256};
    hex(&Sha256::digest(bytes))
}

/// Good-chain fixtures: rebuild the dictionary a streaming receiver would hold by
/// decoding all earlier slices of `source.bin` in that chain family.
fn assemble_chain_dictionary(
    cases: &std::collections::BTreeMap<String, Value>,
    name: &str,
) -> Vec<u8> {
    let family = if name.starts_with("chain_alt_") {
        "chain_alt"
    } else {
        "chain"
    };
    let index: usize = name.rsplit('_').next().unwrap().parse().unwrap();
    let source = source_bytes();
    // Slice bounds come from the manifest entries themselves.
    let mut combined = Vec::new();
    for i in 0..=index {
        let c = &cases[&format!("{family}_{i}")];
        let start = c["slice"][0].as_u64().unwrap() as usize;
        let end = c["slice"][1].as_u64().unwrap() as usize;
        combined.extend_from_slice(&source[start..end]);
    }
    // The block itself is index `index`; its dictionary is everything before it.
    let own_start = cases[name]["slice"][0].as_u64().unwrap() as usize;
    combined.truncate(own_start);
    combined
}

/// State-conflict malformed cases may require presenting a specific dictionary.
fn assemble_bad_dictionary(case: &Value) -> Vec<u8> {
    match case.get("decode_with_dictionary_b64") {
        Some(v) => {
            use base64::Engine;
            base64::engine::general_purpose::STANDARD
                .decode(v.as_str().unwrap())
                .unwrap()
        }
        None => {
            // The "missing predecessor" case is presented with an EMPTY dictionary.
            Vec::new()
        }
    }
}

fn oracle_fixture_has_boundary_match(payload: &[u8]) -> bool {
    let mut cur = 0;
    while cur < payload.len() {
        match payload[cur] {
            format::CTRL_LITERAL => cur += 2,
            format::CTRL_MATCH => {
                if cur + 4 > payload.len() {
                    return false;
                }
                let dist = u16::from_le_bytes([payload[cur + 1], payload[cur + 2]]);
                if dist as usize == WINDOW_BYTES {
                    return true;
                }
                cur += 4;
            }
            format::CTRL_END => return false,
            _ => return false,
        }
    }
    false
}
